ref=db.collection('shoppingLists').document(lid);before=ref.get().to_dict()
assert before and before.get('ownerUid')==owner and before.get('listType')=='template'
assert before['items']==expected or before['items']==items,'Template changed; no overwrite'
docs={s.id:s.to_dict() for s in db.collection('materials').stream()}
patches=[]
for row in photos:
 old=docs[row['id']]
 if row['part']:assert old.get('manufacturerPart')==row['part']
 if old.get('photoUrl'):continue
 response=urllib.request.urlopen(row['url'],timeout=30);assert response.headers.get('Content-Type','').startswith('image/')
 assert len(response.read())>1000
 patch={'photoUrl':row['url'],'photoSource':'verified-manufacturer' if row['part'] else 'manufacturer-visual-reference','photoReferenceNote':row['note'],'photoSourceUrl':row['source'],'updatedAt':firestore.SERVER_TIMESTAMP}
 if not row['part']:patch['brand']='';patch['catalogReviewStatus']='needs-identification'
 patches.append((db.collection('materials').document(row['id']),patch))
for item in items:
 for field in ['matId','referenceMaterialId']:
  if item.get(field):
   m=docs[item[field]];assert m.get('active') is not False and m.get('status')!='inactive'
update={'items':items,'version':3,'sourceImageName':'703CBB64-92B0-4869-944D-FF722D077C4C.png','sourceReviewedAt':'2026-10-14','note':'Fire alarm scope copied from the supplied image: 23 lines. Preserve shown quantities; the ceiling sounder has source quantity 0. Blank quantities and model conflicts require review before creating a purchase. Products with uncertain model or rating use clearly marked visual references. Select the project when using this template.','updatedAt':firestore.SERVER_TIMESTAMP}
@firestore.transactional
def apply(tx):
 current=ref.get(transaction=tx);assert current.to_dict()==before,'Concurrent template edit'
 snapshots=[r.get(transaction=tx) for r,p in patches]
 for snap,(r,p) in zip(snapshots,patches):assert snap.to_dict()==docs[r.id],'Concurrent material edit'
 tx.update(ref,update)
 for r,p in patches:tx.update(r,p)
apply(db.transaction())
saved=ref.get().to_dict();assert saved['items']==items
after={s.id:s.to_dict() for s in db.collection('materials').stream()}
assert set(after)==set(docs),'Unexpected catalog record count change'
for mid,m in docs.items():
 for f in ['qty','sku','active','status','suppliers']:assert after[mid].get(f)==m.get(f),'Stock/code/supplier changed'
def picture(i):
 m=after.get(i.get('matId')) or after.get(i.get('referenceMaterialId')) or {}
 return m.get('photoUrl') or i.get('referencePhotoUrl')
assert all(picture(i) for i in saved['items']),'Missing guided-list image'
assert [i['sourceQty'] for i in saved['items']]==[9,7,9,0,3,3,4,None,None,1,None,1,2,1,2,1,2,1,None,2,2,1,None]
Path('tmp/guided-fire').mkdir(parents=True,exist_ok=True)
needed={i.get(f) for i in saved['items'] for f in ['matId','referenceMaterialId'] if i.get(f)}
fixture={'template':{'id':lid,**{k:saved[k] for k in ['name','note','items','version','ownerUid','useIds','questions']}},'materials':[{'id':mid,**{k:v for k,v in after[mid].items() if k in ['name','sku','cat','unit','photoUrl','photoReferenceNote','active','status','guidedUses','suppliers','brand','manufacturerPart']}} for mid in sorted(needed)],'owner':owner}
Path('tmp/guided-fire/fixture.json').write_text(json.dumps(fixture))
